-module(xls_protocol_inbox_tests).
-moduledoc "Checks the receiver renderer's retained layout, owner identity and failure metadata on a small source-derived inbox. This is a generation regression, not a temporal hardware witness.".
-include_lib("eunit/include/eunit.hrl").

%% Two sender links exercise variable and constant fields beside startup and host slots.
-spec retained_receiver_test_() -> term().
retained_receiver_test_() -> {timeout, 30, fun retained_receiver/0}.

%% Import and inbox composition rebind generated bytes without reallocating source failures.
-spec retained_receiver() -> ok.
retained_receiver() ->
    Build = hls_protocol_transport:plan(#{
        sources => [{"test/hls_protocol_inbox_fixture.erl", []}],
        topology => {hls_protocol_inbox_fixture, topology, []},
        actor_limit => 3, frame_payload_words => 1}),
    #{bundle := #{modules := Modules, topology := #{actors := Actors}},
        capture := Capture, fabric := #{links := Links}} = hls_protocol_transport:descriptor(Build),
    [Sink] = [I || {I, #{id := sink}} <- lists:enumerate(0, Actors)],
    Incoming = [L || L = #{destination_index := I} <- Links, I =:= Sink],
    Source = maps:get(hls_protocol_inbox_fixture, Modules),
    Layout = hls_protocol_inbox:plan(Source, Incoming, Capture, [{go, 7}], true),
    Metadata = hls_protocol_inbox:descriptor(Layout),
    ?assertMatch(#{physical_slots := 6, mask_bits := 8, cursor_bits := 3,
        host := #{offset := 7}, startup := #{offset := 6, count := 1}}, Metadata),
    ?assertEqual(local, hls_protocol_inbox:completion(Layout)),
    Owner = #{emitted := Emitted} = hls_local_actor:render(Source),
    Sites = xls_emitted:sites(Emitted),
    ?assert(Sites =/= []),
    File = <<"actors/actor_0.x">>,
    Imported = #{emitted := Import} = xls_local_owner:import_owner(Owner, File),
    ?assertEqual(#{file => File, dslx_sha256 => hls_generated_files:hash(xls_emitted:bytes(Emitted))},
        maps:get(owner_import, Imported)),
    ?assertEqual(Sites, xls_emitted:sites(Import)),
    Attached = #{emitted := Receiver} = xls_protocol_inbox:attach(Imported, Layout),
    ?assertEqual(Metadata, maps:get(inbox, Attached)),
    ?assertEqual(Sites, xls_emitted:sites(Receiver)),
    Bytes = xls_emitted:bytes(Receiver),
    lists:foreach(fun(Text) -> ?assertNotEqual(nomatch, binary:match(Bytes, Text)) end,
        [<<"import actor_0 as source_owner;">>, <<"const INBOX_SLOTS = u32:8;">>,
         <<"const CAPTURE_SLOTS = u32:6;">>, <<"host_frame: bits[64]">>,
         <<"u32:7 => io.host_frame">>]).
